N=22
out=[[5]*N for _ in range(N)]
def tile(top,left,frame,center):
    for dr in range(5):
        for dc in range(5):
            out[top+dr][left+dc]=center if 1<=dr<=3 and 1<=dc<=3 else frame
for spec in [(3,0,8,9),(5,17,2,4),(9,12,2,3),(12,5,8,1),(16,0,8,2),(16,17,2,9)]: tile(*spec)
print('\n'.join(' '.join(map(str,row)) for row in out))

out2=[[5]*22 for _ in range(22)]
def tile_on(g,top,left,frame,center):
    for dr in range(5):
        for dc in range(5):
            v=center if 1<=dr<=3 and 1<=dc<=3 else frame
            rr,cc=top+dr,left+dc
            if g[rr][cc] not in (5,v):
                print('conflict',rr,cc,g[rr][cc],v)
            g[rr][cc]=v
for spec in [(3,0,8,9),(5,17,2,4),(9,17,2,3),(12,0,8,1),(16,0,8,2),(16,17,2,9)]: tile_on(out2,*spec)
print('\n'.join(' '.join(map(str,row)) for row in out2))
print(len(out2), set(map(len,out2)))
